// ComputedPositionFields Group-level computed fields, resolved at query time from cached prices; never stored. `valuePln` = sum over the asset's priced subassets; `unitsTotal` / `pricePln` / `priceNative` describe the primary subasset. `profitPct`, `avgBuyPricePln`, `avgBuyPriceNative`, `equivalentUnits` and `costlessSubassets` are the asset-level cost group (task 161): they read the SUM of the recorded costs (`totalSpentPln` > 0) over all subassets of the asset - never one row's cost and never the stored `avgBuyPrice`. A null field is omitted from the response; all are omitted when no cost is recorded.
type ComputedPositionFields struct {
	// AvgBuyPriceNative The entry price in the PRIMARY subasset's own `priceCurrency`: `avgBuyPricePln / fx` with fx the CURRENT PLN rate of that currency (the rate `priceNative = pricePln / fx` uses) = `priceNative / (1 + profitPct)`. The PLN cost is fixed, so it moves with the current exchange rate by design. Equals `avgBuyPricePln` when `priceCurrency` is PLN. Omitted whenever `avgBuyPricePln` is omitted or the FX rate is unavailable. Not stored; never derived from the stored `avgBuyPrice`.
	AvgBuyPriceNative *float64 `json:"avgBuyPriceNative,omitempty"`

	// AvgBuyPricePln The asset's ENTRY PRICE in PLN per 1 unit of the PRIMARY subasset: `pricePln / (1 + profitPct)` = `sum(cost) / (sum(value) / pricePln)`, so `avgBuyPricePln x equivalentUnits = sum(cost)` and `pricePln / avgBuyPricePln - 1 = profitPct`. Non-primary holdings are converted at today's prices (no history). Derived from the recorded costs, not from the stored `avgBuyPrice`. Omitted whenever `profitPct` is omitted or is -1. Changing the primary re-expresses the same cost in the new primary's terms. Not stored.
	AvgBuyPricePln *float64 `json:"avgBuyPricePln,omitempty"`

	// CostlessSubassets Tickers (`SubassetDto.ticker`) of the asset's priced subassets that hold units but have no recorded cost (`totalSpentPln` null or <= 0), listed only when an entry price is computed (sum(cost) > 0). Their baseline is assumed to sit inside a sibling's group-level cost - the known limitation of the entry price (a subasset bought without its cost being entered inflates `profitPct` and lowers the entry price). Omitted when there are none.
	CostlessSubassets *[]string `json:"costlessSubassets,omitempty"`
	CurrentPct        *float64  `json:"currentPct,omitempty"`
	DeviationPct      *float64  `json:"deviationPct,omitempty"`

	// EquivalentUnits Primary-equivalent units `valuePln / pricePln`: what all the asset's holdings are worth today in units of the primary; the quantity the entry price averages the cost over (`avgBuyPricePln x equivalentUnits = sum(cost)`). Present whenever the primary is priced, independent of whether any cost is recorded.
	EquivalentUnits *float64 `json:"equivalentUnits,omitempty"`
	PriceNative     *float64 `json:"priceNative,omitempty"`
	PricePln        *float64 `json:"pricePln,omitempty"`

	// ProfitPct Asset-level profit as a fraction (0.1 = +10 %): `sum(value) / sum(cost) - 1`, where sum(cost) = sum of `totalSpentPln` over the asset's subassets whose cost is > 0 and sum(value) = sum of `effectiveUnits x pricePln` over EVERY priced subasset, including those with no recorded cost (the go-live cost of a group sits on the head row). A subasset with a recorded cost but no price contributes neither. Omitted when sum(cost) <= 0 - every portfolioB asset until its reviewed baselines exist - or when the primary is unpriced. Independent of which subasset is primary.
	ProfitPct  *float64 `json:"profitPct,omitempty"`
	UnitsTotal *float64 `json:"unitsTotal,omitempty"`
	ValuePln   *float64 `json:"valuePln,omitempty"`
}

